// copyright holder (NOTICE, "Trademarks"): a fork ships under its own name and
// mark. Revyme is still named where it describes the work's origin, an upstream
// service (Revyme Cloud, credits, the "Made in Revyme" badge) or a compatibility
// identifier that existing projects rely on (`@revyme/runtime`, `Revyme*`
// components, `@generated by Revyme` markers). FORK.md lists the policy.

/** Commit the running build's platform source is at (vite `define`: VITE_SOURCE_COMMIT, else git HEAD); '' when unknown (tests, non-git builds). */
const commit = typeof __NARRATIVES_SOURCE_COMMIT__ === 'string' ? __NARRATIVES_SOURCE_COMMIT__ : '';

/** Public repository of this fork. A deployment from another repository sets VITE_SOURCE_URL. */
const sourceUrl = (import.meta.env.VITE_SOURCE_URL as string | undefined) || 'https://github.com/panchoavila/narratives';

export const BRAND = {
  name: 'Narratives',
  tagline: 'An opinionated Revyme for building immersive narratives.',
  upstream: {
    name: 'Revyme',
    author: 'Nikita Kofman',
    url: 'https://github.com/revyme-web/builder',
  },
  license: {
    name: 'GNU Affero General Public License v3.0',
    spdx: 'AGPL-3.0-only',
    url: 'https://www.gnu.org/licenses/agpl-3.0.html',
  },
  sourceUrl,
  commit,
  /**
   * Where a user of this running build gets its Corresponding Source (AGPL-3.0
   * section 13): the exact commit when the build knows it, else the repository.
   */
  sourceForThisBuild: commit ? `${sourceUrl}/tree/${commit}` : sourceUrl,
} as const;
